import {PARTS,resolve,clone,same} from './armory/model.js';
export {PARTS,clone,same};
export const MODULAR_VERSION=1,MODULAR_SLOTS=['mechanism','barrel','ammo','circuit'],RARITY_WEIGHTS=[.55,.25,.15,.05];
export const STARTER_KIT={mechanism:{id:'automatic',rank:0},barrel:{id:'single',rank:0},ammo:{id:'normal',rank:0},circuit:{id:'momentum',rank:0}};
export const quality=rank=>[1,1.08,1.16,1.25][rank],penalty=rank=>[1,.92,.84,.75][rank];
export function createCollection(){return{version:MODULAR_VERSION,owned:Object.fromEntries(Object.values(STARTER_KIT).map(p=>[p.id,0])),kit:clone(STARTER_KIT),tokens:0,marks:[],shop:null};}
export function normalizeCollection(raw){const c=createCollection();if(!raw||typeof raw!=='object')return c;for(const [id,rank]of Object.entries(raw.owned||{}))if(Object.hasOwn(PARTS,id)&&Number.isInteger(rank)&&rank>=0&&rank<=3)c.owned[id]=Math.max(c.owned[id]??-1,rank);for(const slot of MODULAR_SLOTS){const p=raw.kit?.[slot];if(PARTS[p?.id]?.slot===slot&&Number.isInteger(p.rank)&&c.owned[p.id]!==undefined)c.kit[slot]={id:p.id,rank:c.owned[p.id]};}c.tokens=Math.max(0,Math.floor(Number(raw.tokens)||0));c.marks=Array.isArray(raw.marks)?raw.marks.filter(p=>Number.isFinite(p)&&p>=.3&&p<=.45):[];if(raw.shop&&Number.isInteger(raw.shop.round)&&Array.isArray(raw.shop.choices)&&raw.shop.choices.every(p=>PARTS[p.id]&&Number.isInteger(p.rank)&&p.rank>=0&&p.rank<=3)&&new Set(raw.shop.choices.map(p=>p.id)).size===raw.shop.choices.length)c.shop=clone(raw.shop);return c;}
export function fullCollection(){const c=createCollection();for(const id of Object.keys(PARTS))c.owned[id]=3;for(const slot of MODULAR_SLOTS)c.kit[slot].rank=3;return c;}
export function acquire(c,p){if(!PARTS[p?.id]||!Number.isInteger(p.rank)||p.rank<0||p.rank>3||(c.owned[p.id]??-1)>=p.rank)return false;c.owned[p.id]=p.rank;c.kit[PARTS[p.id].slot]=clone(p);return true;}
export function rarityDistribution(marks=[]){let d=[...RARITY_WEIGHTS];for(const chance of marks){const n=[0,0,0,d[3]];for(let i=0;i<3;i++){n[i]+=d[i]*(1-chance);n[i+1]+=d[i]*chance;}d=n;}return d;}
export function rollShop(c,round,random=Math.random){
 if(c.shop?.round===round)return c.shop;const distribution=rarityDistribution(c.marks),shown=new Set(),choices=[];
 const count=Math.min(Object.keys(PARTS).filter(id=>(c.owned[id]??-1)<3).length,3+c.tokens);
 for(let i=0;i<count;i++){
  const eligible=distribution.map((_,rank)=>Object.keys(PARTS).filter(id=>!shown.has(id)&&(c.owned[id]??-1)<rank)),weights=distribution.map((p,r)=>eligible[r].length?p:0),total=weights.reduce((a,b)=>a+b,0);if(!total)break;
  let roll=random()*total,rank=0;for(;rank<3;rank++){if(roll<weights[rank])break;roll-=weights[rank];}
  const pool=eligible[rank],id=pool[Math.min(pool.length-1,Math.floor(random()*pool.length))];shown.add(id);choices.push({id,rank});
 }
 c.tokens=0;c.marks=[];return c.shop={round,choices,committed:false,draft:null};
}
export function createLife(id=1){return{id,kills:0,stacks:0,slowUntil:0};}
export function rewardKill(c,life){const p=c.kit.circuit,part=PARTS[p.id],u=quality(p.rank);life.kills++;const count=Math.floor(life.kills/part.interval)-life.stacks;life.stacks+=count;const reward={health:0,focus:0,ammoFraction:0,marks:0};if(!count)return reward;if(p.id==='repair')reward.health=35*u*count;if(p.id==='focus')reward.focus=35*u*count;if(p.id==='service')reward.ammoFraction=.20*u*count;if(p.id==='assayer'){reward.marks=count;for(let i=0;i<count;i++)c.marks.push(.30+.05*p.rank);}return reward;}
export function circuitBonuses(c,life={stacks:0}){const p=c.kit.circuit,n=(life.stacks||0)*quality(p.rank),id=p.id;return{damage:id==='pressure'?1+.12*n:1,reload:id==='service'?1+.25*n:1,move:id==='momentum'?1+.06*n:1,focusRegen:id==='focus'?1+.15*n:1,rebound:id==='rebound'?.60*n:0,slow:id==='brake'?.35*n:0,echo:id==='echo'?life.stacks||0:0,echoScale:.40*quality(p.rank),arc:id==='arc'?.60*n:0};}
export function gunStats(c,life={},motor=1){const kit=c.kit||c,b=resolve(kit),mr=kit.mechanism.rank,br=kit.barrel.rank,ar=kit.ammo.rank,bu=quality(br),bp=penalty(br),au=quality(ar),ap=penalty(ar),bonus=c.kit?circuitBonuses(c,life):circuitBonuses({kit:{circuit:{id:'momentum',rank:0}}},{}),aid=kit.ammo.id,bid=kit.barrel.id,charged=kit.mechanism.id==='charge';
 let factor=b.B.cycle;if(bid==='gatling')factor=.9+Math.max(0,Math.min(1,motor))*(factor-.9);const gap=b.M.gap*factor*b.A.cycle,charge=charged?Math.max(.18,Math.min(.6,b.M.charge*factor)):0,recovery=charged?(b.M.cycle-b.M.charge)*factor*b.A.cycle:0,cycle=charged?charge+recovery:b.M.cycle*factor*b.A.cycle,G=b.M.count>1?gap:cycle,pair=b.B.packets===2?Math.min(.065*bp,.4*G):0,tandem=aid==='duplex'?Math.min(.035,.4*(pair?Math.min(pair,G-pair):G)):0;
 const radiusBase={normal:.035,pellets:.025,sniper:.025,explosive:.06,piercing:.035,duplex:.035}[aid],velocity={normal:180,pellets:150,sniper:300,explosive:60,piercing:220,duplex:180}[aid]*au*(bid==='huge'?1-.15*bp:1)*(charged?1.6:1),pattern=(aid==='pellets'?ap:1)*(bid==='huge'?1+.20*bp:bid==='gatling'?1+.15*bp:bid==='rails'?1-.45*bu:1)*(charged?.6:1),radius=radiusBase*(bid==='huge'?1+.5*bu:1)*(charged?1.5:1),blast=aid==='explosive'?2.4*au*(bid==='huge'?1+.35*bu:bid==='gatling'?1-.20*bp:bid==='rails'?1-.15*bp:1)*(charged?1.15:1):0;
 const curves={normal:[22,45,.75],pellets:[8,24,.75],sniper:[40,70,.9],piercing:[22,45,.8],duplex:[22,45,.75]},curve=curves[aid],head=1+(b.A.head-1)*au,projectiles=aid==='pellets'?8:aid==='duplex'?2:1,baseDamage=b.damage,damageBudget=baseDamage*bonus.damage;
 return{...b,kit:clone(kit),bonus,modular:true,name:'Modular gun',mechanism:kit.mechanism.id,barrel:bid,ammoType:aid,baseDamage,damageBudget,damage:damageBudget/(b.B.packets*projectiles)*(aid==='explosive'?.65:1),splash:aid==='explosive'?damageBudget/b.B.packets*.35:0,pellets:projectiles,volley:b.B.packets,burst:b.M.count,burstGap:gap,pairDelay:pair,tandem,charge,chargePrep:charge,recovery,cycle,interval:cycle,mag:b.capacity,cost:b.M.count*b.B.packets,reload:b.reload/bonus.reload,mode:kit.mechanism.id==='automatic'?'auto':kit.mechanism.id==='semi'?'semi':kit.mechanism.id==='burst'?'burst':'charge',payload:aid==='explosive'?'explosive':aid==='piercing'?'penetrator':aid==='pellets'?'buckshot':aid==='duplex'?'duplex':'bullet',radius,velocity,instant:bid==='rails',pattern,blast,headMultiplier:head,penetration:aid==='piercing'?[1,1-.2*ap,1-.4*ap]:[1],falloff:curve?{close:Math.min(90,curve[0]*au),far:Math.min(90,curve[1]*au),near:1,farScale:1-(1-curve[2])*ap}:undefined,spread:0,range:90,idealRange:aid==='pellets'?8:aid==='sniper'||bid==='rails'?24:16,spinUp:.35*bp,move:bonus.move,recoil:bid==='huge'?1.35:.8,ads:1,switch:1,adsMove:1,core:1,zoom:aid==='sniper'?1.7:1.2,color:0xf0c17d,feedMode:'standard',handling:'',selfDamage:0,jump:0};
}
export function migrateModularRun(saved){if(!saved||!Number.isInteger(saved.round)||saved.round<1)return null;if(saved.modularVersion===MODULAR_VERSION)return{...saved,collection:normalizeCollection(saved.collection)};const c=createCollection();const old=saved.equipped??saved.startingWeapon??0;const mechanisms=['automatic','semi','automatic','charge','charge','semi'],ammo=['normal','normal','normal','sniper','explosive','pellets'];for(const [slot,id]of [['mechanism',mechanisms[old]||'automatic'],['ammo',ammo[old]||'normal']]){c.owned[id]=0;c.kit[slot]={id,rank:0};}for(const b of Object.values(saved.builds||{}))for(const id of b?.owned||[]){const p=/charge|capacitor|siege/.test(id)?'charge':/burst|ratchet|cam/.test(id)?'burst':/duplex/.test(id)?'duplex':/frag|blast|explos|demolition|breach/.test(id)?'explosive':/penetr|needle|through|flechette/.test(id)?'piercing':/slug|surveyor/.test(id)?'sniper':/drum|box/.test(id)?'gatling':/feed|magazine|reload|tube/.test(id)?'single':'normal';c.owned[p]=0;}for(const id of Object.keys(saved.perks||{})){const p={reload:'service',speed:'momentum',armor:'repair',focus:'focus',quickdraw:'pressure',recovery:'repair'}[id];if(p)c.owned[p]=0;}return{...saved,modularVersion:MODULAR_VERSION,collection:c,credits:0,owned:[0],equipped:0,perks:{},shopOffers:null};}
export function botTokenSkill(round){const t=Math.max(0,Math.min(1,(round-1)/7));return{interest:t,reaction:.9-.75*t,replan:.9-.7*t,range:8+32*t,contest:.1+.8*t};}
export function chooseBotUpgrade(c,round,index=0,random=Math.random){const shop=rollShop(c,round,random);if(shop.committed)return null;let best=null,score=-Infinity;const old=gunStats(c);for(const p of shop.choices){const trial=normalizeCollection(c);acquire(trial,p);const w=gunStats(trial),preference=[['gatling','pellets','momentum'],['burst','duplex','service'],['rails','sniper','charge'],['double','piercing','echo'],['huge','explosive','arc']][index%5],value=Math.log(w.damageBudget/w.cycle/(old.damageBudget/old.cycle))*.6+Math.log(w.mag/Math.max(1,w.cost))*.08+p.rank*.3+(preference.includes(p.id)?.65:0)+random()*(1.2-Math.min(round,8)*.1);if(value>score){best=p;score=value;}}if(best)acquire(c,best);shop.committed=true;shop.pick=best;return best;}
